<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { api } from '@/api/client'
type Tournament={id:number;name:string};type Registration={id:number};type Match={id:number;round_number:number;match_number:number;player_one_registration_id?:number;player_two_registration_id?:number;winner_registration_id?:number;starts_at?:string;score?:string;status:string}
const props=defineProps<{tournaments:Tournament[]}>();const client=useQueryClient();const tournamentId=ref<number>();const facilityId=ref<number>();const branchId=ref<number>();const courtId=ref<number>();const p1=ref<number>();const p2=ref<number>();const round=ref(1);const number=ref(1);const starts=ref('');const msg=ref('');const err=ref('');const selected=computed(()=>tournamentId.value)
const facilities=useQuery({queryKey:['facilities'],queryFn:async()=>((await api.get('/facilities')).data.data??[])});const branches=useQuery({queryKey:computed(()=>['match-branches',facilityId.value]),enabled:computed(()=>!!facilityId.value),queryFn:async()=>((await api.get(`/facilities/${facilityId.value}/branches`)).data.data??[])});const courts=useQuery({queryKey:computed(()=>['match-courts',branchId.value]),enabled:computed(()=>!!branchId.value),queryFn:async()=>((await api.get(`/branches/${branchId.value}/courts`)).data.data??[])});const registrations=useQuery({queryKey:computed(()=>['tournament-registrations',selected.value]),enabled:computed(()=>!!selected.value),queryFn:async()=>{const r=await api.get(`/tournaments/${selected.value}/registrations`);return r.data.data??r.data??[]}});const matches=useQuery({queryKey:computed(()=>['tournament-matches',selected.value]),enabled:computed(()=>!!selected.value),queryFn:async()=>{const r=await api.get(`/tournaments/${selected.value}/matches`);return r.data.data??r.data??[]}});const registrationList=computed<Registration[]>(()=>registrations.data.value??[]);const matchList=computed<Match[]>(()=>matches.data.value??[])
async function refresh(){await client.invalidateQueries({queryKey:['tournament-matches',selected.value]})}async function create(){if(!selected.value){err.value='Select a tournament.';return}try{await api.post(`/tournaments/${selected.value}/matches`,{court_id:courtId.value||undefined,player_one_registration_id:p1.value||undefined,player_two_registration_id:p2.value||undefined,round_number:round.value,match_number:number.value,starts_at:starts.value||undefined});msg.value='Match scheduled.';await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not schedule match.'}}async function result(match:Match,winner?:number){try{await api.patch(`/tournament-matches/${match.id}`,{status:'completed',score:match.score,winner_registration_id:winner});await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not record result.'}}</script>
<template><section class="panel membership-form payment-form"><h2>Match management</h2><label>Tournament<select v-model.number="tournamentId"><option :value="undefined">Select tournament</option><option v-for="t in props.tournaments" :key="t.id" :value="t.id">{{t.name}}</option></select></label><form @submit.prevent="create"><div class="form-grid"><label>Facility<select v-model.number="facilityId" @change="branchId=undefined;courtId=undefined"><option :value="undefined">Select facility</option><option v-for="f in facilities.data.value??[]" :key="f.id" :value="f.id">{{f.name}}</option></select></label><label>Branch<select v-model.number="branchId" :disabled="!facilityId" @change="courtId=undefined"><option :value="undefined">Select branch</option><option v-for="b in branches.data.value??[]" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>Court<select v-model.number="courtId" :disabled="!branchId"><option :value="undefined">No court assigned</option><option v-for="court in courts.data.value??[]" :key="court.id" :value="court.id">{{court.name}}</option></select></label><label>Player one<select v-model.number="p1"><option :value="undefined">TBD</option><option v-for="player in registrationList" :key="player.id" :value="player.id">Registration #{{player.id}}</option></select></label><label>Player two<select v-model.number="p2"><option :value="undefined">TBD</option><option v-for="player in registrationList" :key="player.id" :value="player.id">Registration #{{player.id}}</option></select></label><label>Round<input v-model.number="round" type="number" min="1"/></label><label>Match number<input v-model.number="number" type="number" min="1"/></label><label>Starts<input v-model="starts" type="datetime-local"/></label></div><button class="secondary-button">Schedule match</button></form><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p></section><section v-if="tournamentId" class="panel memberships-table"><h2>Bracket and results</h2><div class="table-wrap"><table><thead><tr><th>Round</th><th>Match</th><th>Players</th><th>Result</th><th>Actions</th></tr></thead><tbody><tr v-for="match in matchList" :key="match.id"><td>{{match.round_number}}</td><td>#{{match.match_number}}</td><td>#{{match.player_one_registration_id||'TBD'}} vs #{{match.player_two_registration_id||'TBD'}}</td><td>{{match.score||'—'}}</td><td><button v-if="match.status!=='completed'" class="table-button" @click="result(match,match.player_one_registration_id)">P1 wins</button> <button v-if="match.status!=='completed'" class="table-button" @click="result(match,match.player_two_registration_id)">P2 wins</button><span v-else>{{match.status}}</span></td></tr></tbody></table></div></section></template>
